def version_key(text):
    parts=text.split('.')
    if any(not p or not p.isascii() or not p.isdecimal() for p in parts): raise ValueError('version')
    result=[int(p) for p in parts]
    while len(result)>1 and result[-1]==0: result.pop()
    return tuple(result)

